ON CONFLICT (id) DO UPDATE SET
    synopsis = EXCLUDED.synopsis, release_date = EXCLUDED.release_date, end_date = NULL,
    showing_status = EXCLUDED.showing_status, poster_url = EXCLUDED.poster_url
WHERE movies.synopsis LIKE 'Phim %; ngày phát hành hiển thị chỉ dùng thử nghiệm; chưa có suất chiếu.';
INSERT INTO movie_genres (movie_id, genre_id)
SELECT movie.id, CASE WHEN movie.original_title LIKE 'Spider-Man:%Spider-Verse' THEN 4
    WHEN movie.original_title LIKE 'Harry Potter%' OR movie.original_title LIKE 'The Lord%' OR movie.original_title LIKE 'The Hobbit%' THEN 7 ELSE 1 END
FROM movies movie WHERE movie.id BETWEEN '12000000-0000-0000-0000-000000000001'::uuid AND '12000000-0000-0000-0000-000000000040'::uuid
ON CONFLICT DO NOTHING;
COMMIT;
